window.docContents[74].resolve({"/Elementary-Functions/___4___11-Sums/#chapter-4-section-11":{"contents":"Source: NIST Digital Library of Mathematical Functions, §4.11.\n\nSection 4.11 is a reference section rather than a formula section.  It\ncontains no numbered displays, tables, or graphics.  For infinite series\ninvolving logarithms or exponentials, the DLMF directs the reader to the\nspecialist references listed on the source page: Gradshteyn and Ryzhik,\nHansen, and Prudnikov and collaborators.  The neighboring sections are\n§4.10 on integrals and §4.12 on generalized logarithms and exponentials.\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions","header":"4.11. §4.11 Sums","id":"/Elementary-Functions/___4___11-Sums/#chapter-4-section-11"}});